def _slurp(path):
    if not os.path.exists(path):
        raise AnsibleError("imported module support code does not exist at %s" % os.path.abspath(path))
    with open(path, 'rb') as fd:
        data = fd.read()
    return data


def _extract_interpreter(b_module_data):
    """Return the interpreter and arguments from the first line of a module."""
    b_first_line = b_module_data.split(b'\n', 1)[0]
    if not b_first_line.startswith(b'#!'):
        return None, []

    # shlex needs bytes on Python 2 and text on Python 3.
    words = shlex.split(to_native(b_first_line[2:], errors='surrogate_or_strict'))
    words = [to_text(word, errors='surrogate_or_strict') for word in words]
    if not words:
        return None, []
    return words[0], words[1:]


def _get_shebang(interpreter, task_vars, templar, args=tuple(), remote_is_local=False):
    """Resolve an interpreter override and return its complete shebang."""
    has_interpreter = bool(interpreter)
    if not interpreter:
        interpreter = u'/usr/bin/python'

    interpreter_name = os.path.basename(interpreter).strip()
    shebang_args = args

    # For env shebangs, the interpreter being configured is the command passed
    # to env.  Retain the env invocation unless an override is selected.
    if interpreter_name == 'env' and args:
        env_args = list(args)
        if env_args[0] == '-S':
            env_args = env_args[1:]
            if env_args:
                env_args = shlex.split(env_args[0]) + env_args[1:]
        if env_args and not env_args[0].startswith('-') and '=' not in env_args[0]:
            interpreter_name = os.path.basename(env_args[0]).strip()
            shebang_args = env_args[1:]

    is_python = interpreter_name.startswith(('python', 'pypy'))

    # name for interpreter var
    interpreter_config = u'ansible_%s_interpreter' % (u'python' if is_python else interpreter_name)
    # key for config
    interpreter_config_key = "INTERPRETER_%s" % (u'PYTHON' if is_python else interpreter_name.upper())

    interpreter_out = None

    # A module shebang takes precedence over the default automatic discovery
    # setting.  Explicit inventory, environment and config values still win.
    if is_python and C.config.get_configuration_definition(interpreter_config_key):
        configured_interpreter, origin = C.config.get_config_value_and_origin(interpreter_config_key, variables=task_vars)
        if origin != 'default' or not has_interpreter:
            if configured_interpreter:
                configured_interpreter = templar.template(configured_interpreter.strip())
            if configured_interpreter in ('auto', 'auto_legacy', 'auto_silent', 'auto_legacy_silent'):
                interpreter_out = task_vars.get('ansible_facts', {}).get('discovered_interpreter_python')
            else:
                interpreter_out = configured_interpreter

    if is_python and not interpreter_out and remote_is_local and not has_interpreter:
        interpreter_out = task_vars.get('ansible_playbook_python')

    elif interpreter_config in task_vars:
        # for non python we consult vars for a possible direct override
        interpreter_out = templar.template(task_vars.get(interpreter_config).strip())

    if not interpreter_out:
        interpreter_out = interpreter

    shebang = u'#!' + interpreter_out
    if args:
        output_args = shebang_args if interpreter_out != interpreter else args
        if output_args:
            shebang += u' ' + u' '.join(output_args)

    return shebang, interpreter_out


